  </div>
</template>

<script setup lang="ts">
import { computed, unref } from 'vue'
import { useSlideContext } from '@slidev/client'

const props = withDefaults(defineProps<{
  bgColor?: string
  bg?: string
  whiteColor?: string
  patternColor?: string
  color?: string
  blackColor?: string
  oddBgColor?: string
  oddPatternColor?: string
  alternateOdd?: boolean
  opacity?: number | string
  patternOpacity?: number | string
  transparency?: number | string
  bgPattern?: boolean
  preserveAspectRatio?: string
  class?: string
}>(), {
  preserveAspectRatio: 'xMidYMid slice',
})

let slideContext: any = null
try {
  slideContext = useSlideContext()
} catch {}

const frontmatter = computed(() => unref(slideContext?.$frontmatter) || {})

const currentPage = computed(() => {
  if (!slideContext) return 0
  const p1 = unref(slideContext.$page)
  if (typeof p1 === 'number') return p1
  if (p1 && typeof p1.value === 'number') return p1.value
  
  const p2 = unref(slideContext.$nav?.currentPage)
  if (typeof p2 === 'number') return p2
  if (p2 && typeof p2.value === 'number') return p2.value

  const p3 = unref(slideContext.$nav?.currentSlideNo)
  if (typeof p3 === 'number') return p3
  if (p3 && typeof p3.value === 'number') return p3.value

  return 0
})

const isOddPage = computed(() => {
  return currentPage.value > 0 && currentPage.value % 2 !== 0
})

const isAlternateEnabled = computed(() => {
  if (props.alternateOdd !== undefined) return props.alternateOdd
  if (frontmatter.value.alternateOdd !== undefined) return frontmatter.value.alternateOdd
  if (frontmatter.value.alternateColors !== undefined) return frontmatter.value.alternateColors
  return true
})

const shouldAlternate = computed(() => {
  return isOddPage.value && isAlternateEnabled.value
})

const showPattern = computed(() => {
  if (props.bgPattern === false) return false
  if (frontmatter.value.bgPattern === false) return false

  if (props.bgPattern === true) return true
  if (frontmatter.value.bgPattern === true) return true

  return true
})

// Dynamic Background Color Fill (Área blanca del SVG original)
const computedBgColor = computed(() => {
  // Colores específicos para página impar
  if (shouldAlternate.value) {
    if (props.oddBgColor || frontmatter.value.oddBgColor) {
      return props.oddBgColor || frontmatter.value.oddBgColor
    }
  }

  // Props/Frontmatter explícitos
  const explicitBg = props.whiteColor ||
    props.bgColor || 
    props.bg || 
    frontmatter.value.whiteColor ||
    frontmatter.value.bgColor || 
    frontmatter.value.bg

  if (explicitBg) return explicitBg

  // Alternancia automática en páginas impares (Turquesa Calmécac)
  if (shouldAlternate.value) {
    return '#00B09B'
  }

  // Páginas pares: Negro Monolítico de fondo
  return '#09090B'
})

// Dynamic Pattern Path Color (Área negra del SVG original)
const computedPatternColor = computed(() => {
  // Colores específicos de patrón para página impar
  if (shouldAlternate.value) {
    if (props.oddPatternColor || frontmatter.value.oddPatternColor) {
      return props.oddPatternColor || frontmatter.value.oddPatternColor
    }
  }

  // Props/Frontmatter explícitos
  const explicitPattern = props.blackColor ||
    props.patternColor || 
    props.color || 
    frontmatter.value.blackColor ||
    frontmatter.value.patternColor || 
    frontmatter.value.color || 
    frontmatter.value.bgPatternColor

  if (explicitPattern) return explicitPattern

  // Alternancia automática en páginas impares (Negro Monolítico)
  if (shouldAlternate.value) {
    return '#09090B'
  }

  // Páginas pares: Turquesa Calmécac
  return '#00B09B'
})

// Dynamic Pattern Opacity - Equilibrada para elegancia y máxima legibilidad de texto
const computedPatternOpacity = computed(() => {
  const rawOpacity = props.patternOpacity ?? 
    props.opacity ?? 
    props.transparency ?? 
    frontmatter.value.patternOpacity ?? 
    frontmatter.value.bgPatternOpacity ?? 
    frontmatter.value.bgOpacity ?? 
    frontmatter.value.opacity

  if (rawOpacity !== undefined && rawOpacity !== null) {
    const num = typeof rawOpacity === 'string' ? parseFloat(rawOpacity) : rawOpacity
    if (!isNaN(num)) {
      return num
    }
  }

  // En página impar alternada con fondo turquesa, patrones negros nítidos (65%)
  if (shouldAlternate.value) {
    return 0.65
  }

  // En páginas pares (fondo negro monolítico), líneas turquesa VIBRANTES y muy visibles (75%)
  return 0.75
})
</script>
